def full_payload(data):
    parents = data["allowed_parent_claim_ids"][:8]
    designs = []
    for topic, intervention, metric in (
        ("ясность расписания", "Сравнить описание организации дня с текущим сообщением", "Доля квалифицированных обращений"),
        ("соответствие формата потребности", "Добавить обсуждение потребности семьи перед выбором формата", "Доля обращений с подтверждённым соответствием формата"),
        ("понятность следующего шага", "Объяснить порядок знакомства и обращения без новых обещаний", "Доля предметных запросов о знакомстве"),
    ):
        designs.append(dict(
            hypothesis=f"Проверяемое направление — {topic}; более понятное сообщение может помочь семье принять решение об обращении. Эффект требует наблюдения.",
            target_metric=metric + "; определение события и способ учёта согласовать до запуска.",
            intervention=intervention + ". Сохранить одинаковые условия и зарегистрировать изменения каналов и работы менеджера.",
            expected_signal="Ожидается направленное улучшение качества обращений без роста жалоб; это гипотеза, а не прогноз или обещание результата.",
            failure_condition="Нет согласованного улучшения либо ухудшается качество обращений. Неполные или несопоставимые данные означают неопределённый результат.",
            minimum_required_inputs=["Исходная частота события и доступный поток аудитории", "Определение квалификации и надёжная регистрация", "Правила сопоставимого распределения и ограничения ресурсов"],
            time_resource_constraints=[], related_strategic_claim_ids=parents,
        ))
    return dict(outputs=[dict(output_name=name, text=FINDINGS[name], kind="HYPOTHESIS",
        confidence="MEDIUM", evidence_ids=[], parent_claim_ids=parents)
        for name in data["expected_outputs"]], experiments=designs,
        assumptions=["Сопоставимость аудитории и условий требует проверки."],
        limitations=["Нет исходной частоты события, оценки доступной аудитории и экономических данных; формальное планирование ограничено."])


class ExperimentsProvider:
    def __init__(self, mutate=None):
        self.calls = []
        self.mutate = mutate

    def __call__(self, request):
        call = json.loads(request.content)
        self.calls.append(call)
        data = json.loads(call["input"][1]["content"])
        payload = full_payload(data)
        if self.mutate:
            self.mutate(payload)
        return httpx.Response(200, json={"status": "completed", "output_text": json.dumps(payload, ensure_ascii=False)})
